{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Afatinib, the closest analogue sharing the 4-anilinoquinazoline core and the same butenamide side-chain motif, showed good oral bioavailability in human Phase I studies, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Simotinib, a close 4-anilinoquinazoline analogue with the same 3-chloro-4-fluoroanilino and methoxy substituents, was concluded to be orally bioavailable in NSCLC patients.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Gefitinib, a related 4-anilinoquinazoline EGFR inhibitor, has an oral bioavailability of about 60% in humans, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Erlotinib, another 4-anilinoquinazoline, has oral bioavailability of 76% in cancer patients and about 59% in healthy subjects, demonstrating high F for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Gefitinib (ZD1839) showed 57% oral bioavailability in healthy volunteers, further supporting high F for closely related quinazoline EGFR inhibitors.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Selatinib, a related quinazoline analogue, showed high oral bioavailability in healthy Chinese subjects, supporting the same direction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Zongertinib, a structurally related quinazoline, was predicted to have 41% human oral bioavailability, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Avanafil, a structurally unrelated PDE5 inhibitor, has 8-10% oral bioavailability, but its low similarity to the query limits transferability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C08"],
      "claim": "Pyronaridine, a structurally unrelated antimalarial, appears to have low bioavailability, but low similarity to the query limits relevance.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a 4-anilinoquinazoline EGFR inhibitor closely related to afatinib, simotinib, gefitinib, and erlotinib, all of which show oral bioavailability well above 20% in humans. The closest analogue, afatinib, has good oral bioavailability, and multiple related quinazoline kinase inhibitors support high F. The physicochemical prior is mixed, but the strong transferable experimental evidence from close analogues outweighs it.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the query molecule.",
    "Afatinib's absolute bioavailability in humans was not formally determined, though oral exposure was good.",
    "Query-specific solubility, metabolic stability, and first-pass extraction are not experimentally characterized."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

